import React from 'react';

const Projects = () => {
    const sectionStyle = {
        padding: '2rem',
        backgroundColor: '#f9f9f9',
        fontFamily: 'Arial, sans-serif',
        lineHeight: '1.6',
    };

    const headingStyle = {
        fontSize: '2.5rem',
        color: '#333',
        textAlign: 'center',
        marginBottom: '2rem',
    };

    const projectListStyle = {
        listStyleType: 'none',
        padding: '0',
        margin: '0 auto',
        maxWidth: '800px',
    };

    const projectItemStyle = {
        backgroundColor: '#fff',
        borderRadius: '8px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        padding: '1.5rem',
        marginBottom: '1.5rem',
        transition: 'transform 0.2s',
    };

    const projectItemHoverStyle = {
        transform: 'scale(1.02)',
    };

    const projectTitleStyle = {
        fontSize: '1.8rem',
        color: '#007bff',
        marginBottom: '0.5rem',
    };

    const projectDescriptionStyle = {
        fontSize: '1.2rem',
        color: '#555',
        marginBottom: '0.5rem',
    };

    const projectTechStyle = {
        fontSize: '1rem',
        color: '#777',
    };

    return (
        <section style={sectionStyle}>
            <h1 style={headingStyle}>Projects</h1>
            <ul style={projectListStyle}>
                <li
                    style={projectItemStyle}
                    onMouseOver={(e) => (e.currentTarget.style.transform = projectItemHoverStyle.transform)}
                    onMouseOut={(e) => (e.currentTarget.style.transform = 'none')}
                >
                    <h2 style={projectTitleStyle}>Project 1</h2>
                    <p style={projectDescriptionStyle}>Description: [Project Description]</p>
                    <p style={projectTechStyle}>Technologies: [Tech Stack]</p>
                </li>
                <li
                    style={projectItemStyle}
                    onMouseOver={(e) => (e.currentTarget.style.transform = projectItemHoverStyle.transform)}
                    onMouseOut={(e) => (e.currentTarget.style.transform = 'none')}
                >
                    <h2 style={projectTitleStyle}>Project 2</h2>
                    <p style={projectDescriptionStyle}>Description: [Project Description]</p>
                    <p style={projectTechStyle}>Technologies: [Tech Stack]</p>
                </li>
            </ul>
        </section>
    );
};

export default Projects;
